CREATE TABLE support_tickets(workspace_id uuid NOT NULL,id uuid NOT NULL,reporter_user_id uuid NOT NULL,category text NOT NULL,severity text NOT NULL CHECK(severity IN('low','normal','high','urgent')),subject text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','waiting','resolved','closed')),diagnostic_consent boolean NOT NULL DEFAULT false,assignee text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE support_ticket_messages(workspace_id uuid NOT NULL,id uuid NOT NULL,ticket_id uuid NOT NULL,author_user_id uuid NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,ticket_id)REFERENCES support_tickets(workspace_id,id));
CREATE TABLE diagnostic_bundles(workspace_id uuid NOT NULL,id uuid NOT NULL,ticket_id uuid NOT NULL,preview jsonb NOT NULL,state text NOT NULL DEFAULT 'awaiting_consent' CHECK(state IN('awaiting_consent','building','ready','expired','revoked')),checksum text,expires_at timestamptz NOT NULL,created_by uuid NOT NULL,PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,ticket_id)REFERENCES support_tickets(workspace_id,id));
CREATE TABLE contact_requests(id uuid PRIMARY KEY,email text NOT NULL,company text,purpose text NOT NULL,message text NOT NULL,consent_version text NOT NULL,abuse_decision text NOT NULL,state text NOT NULL DEFAULT 'received' CHECK(state IN('received','queued','routed','retry','dead_letter','deleted')),routing_receipt text,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE offline_devices(workspace_id uuid NOT NULL,id uuid NOT NULL,user_id uuid NOT NULL,installation_id text NOT NULL,capabilities jsonb NOT NULL,key_lease_expires_at timestamptz,proof_epoch integer NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked','deletion_pending','deleted')),last_activated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,user_id,installation_id));
CREATE TABLE push_subscriptions(workspace_id uuid NOT NULL,id uuid NOT NULL,user_id uuid NOT NULL,endpoint_hash text NOT NULL,encrypted_subscription text NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','expired','revoked')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(endpoint_hash));
CREATE TABLE guest_invitations(workspace_id uuid NOT NULL,id uuid NOT NULL,email text NOT NULL,resource_type text NOT NULL,resource_id uuid NOT NULL,scopes jsonb NOT NULL,token_hash text NOT NULL,expires_at timestamptz NOT NULL,max_uses integer NOT NULL DEFAULT 1,use_count integer NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','accepted','revoked','expired')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE guest_sessions(workspace_id uuid NOT NULL,id uuid NOT NULL,invitation_id uuid NOT NULL,device_label text NOT NULL,verifier_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,invitation_id)REFERENCES guest_invitations(workspace_id,id));
DO $$ DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['support_tickets','support_ticket_messages','diagnostic_bundles','offline_devices','push_subscriptions','guest_invitations','guest_sessions']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING(knotline_tenant_visible(workspace_id))WITH CHECK(knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON support_tickets,support_ticket_messages,diagnostic_bundles,contact_requests,offline_devices,push_subscriptions,guest_invitations,guest_sessions FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON support_tickets,support_ticket_messages,diagnostic_bundles,offline_devices,push_subscriptions,guest_invitations,guest_sessions TO knotline_runtime;
GRANT INSERT ON contact_requests TO knotline_runtime;
GRANT SELECT ON support_tickets,support_ticket_messages,diagnostic_bundles,contact_requests,offline_devices,push_subscriptions,guest_invitations,guest_sessions TO knotline_reporting;
